final class OptionDisplayControl: NSView, OptionControl {
    private let fixedWidth: CGFloat
    private let read: () -> String
    private let enabled: () -> Bool
    private(set) var text = ""

    init(width: CGFloat, read: @escaping () -> String, enabled: @escaping () -> Bool) {
        self.fixedWidth = width
        self.read = read
        self.enabled = enabled
        super.init(frame: .zero)
        wantsLayer = true
        refresh()
    }

    }

    func controlTextDidChange(_ obj: Notification) {
        changed(stringValue)
    }

    func control(
        _ control: NSControl, textView: NSTextView, doCommandBy commandSelector: Selector
    ) -> Bool {
        guard commandSelector == #selector(NSResponder.cancelOperation(_:)) else { return false }
        // Handled here rather than by letting the field editor end: an empty
        // field with the caret still in it is what a person pressing Escape in
        // a search box is asking for.
        guard !stringValue.isEmpty else { return false }
        stringValue = ""
        changed("")
        return true
    }
}

