1371	    override func draw(_ dirtyRect: NSRect) {
1372	        guard let owner = timeline else { return }
1373	        let layout = owner.layout
1374	        let snapshot = owner.snapshot
1375	
1376	        DS.timelineLane.setFill()
1377	        dirtyRect.fill()
1378	
1379	        for row in 0..<max(layout.trackCount, 0) {
1380	            let rect = layout.rowRect(row, width: layout.contentWidth)
1381	            guard rect.intersects(dirtyRect) else { continue }
1382	            (row.isMultiple(of: 2) ? DS.timelineLaneAlt : DS.timelineLane).setFill()
1383	            rect.fill()
1384	        }
1385	
1386	        if let range = owner.inOutRange, range.end > range.start, layout.trackCount > 0 {
1387	            DS.timelineRangeShade.setFill()
1388	            NSRect(
1389	                x: layout.x(for: range.start), y: layout.lanesTop,
1390	                width: layout.width(of: range.end - range.start),
1391	                height: layout.lanesHeight
1392	            ).fill()
1393	        }
1394	        drawCandidateSpans(owner: owner, layout: layout)
1395	
1396	        for (index, track) in snapshot.tracks.enumerated() {
1397	            let row = layout.row(forTrackIndex: index)
1398	            let lane = layout.rowRect(row, width: layout.contentWidth)
1399	            guard lane.intersects(dirtyRect) else { continue }
1400	            drawClips(
1401	                snapshot.clips(onTrack: track.id), row: row, track: track, owner: owner,
1402	                dirtyRect: dirtyRect)
1403	            if track.locked {
1404	                TimelineDraw.hatch(lane, color: DS.textFaint.withAlphaComponent(0.55))
1405	            }
1406	        }
1407	
1408	        drawOverlays(owner: owner, layout: layout)
1409	    }
