1411	    private func drawOverlays(owner: TimelineView, layout: TimelineLayout) {
1412	        if let marquee = owner.marquee {
1413	            let rect = marquee.rect
1414	            DS.selectionFill.setFill()
1415	            rect.fill()
1416	            DS.marquee.setStroke()
1417	            NSBezierPath(rect: rect.insetBy(dx: 0.5, dy: 0.5)).stroke()
1418	        }
1419	
1420	        let guide =
1421	            owner.clipDrag?.guide ?? owner.trim?.guide ?? owner.roll?.guide
1422	            ?? owner.markerDrag?.guide
1423	        if let guide = guide {
1424	            DS.snapGuide.setFill()
1425	            NSRect(x: layout.x(for: guide) - 0.5, y: 0, width: 1, height: bounds.height).fill()
1426	        }
1427	
1428	        DS.playhead.setFill()
1429	        NSRect(
1430	            x: (layout.x(for: owner.playhead) - 0.5).rounded(), y: layout.lanesTop - 2,
1431	            width: 1, height: max(layout.lanesHeight + 4, 0)
1432	        ).fill()
1433	
1434	        if let refusal = owner.refusal {
1435	            let t = min(max(refusal.progress, 0), 1)
1436	            // The SIZE is interpolated too, not just the origin. Lanes used to
1437	            // be one height, so carrying `from`'s size was free; they are now
1438	            // per kind (`DS.trackHeights`), and a refused drop from a 60 pt
1439	            // audio lane onto a 44 pt text lane would land a ghost 16 pt taller
1440	            // than the clip it springs back to.
1441	            let rect = CGRect(
1442	                x: refusal.from.minX + (refusal.to.minX - refusal.from.minX) * t,
1443	                y: refusal.from.minY + (refusal.to.minY - refusal.from.minY) * t,
1444	                width: refusal.from.width + (refusal.to.width - refusal.from.width) * t,
1445	                height: refusal.from.height + (refusal.to.height - refusal.from.height) * t)
1446	            DS.playhead.withAlphaComponent(0.75 * (1 - t) + 0.25).setStroke()
1447	            let path = NSBezierPath(
1448	                roundedRect: rect.insetBy(dx: 1, dy: 1),
1449	                xRadius: TimelineLayout.clipRadius, yRadius: TimelineLayout.clipRadius)
1450	            path.lineWidth = 2
1451	            path.stroke()
1452	        }
1453	        drawActionDragOverlay(owner: owner, layout: layout)
1454	    }
1455	}
