1457	// MARK: - Ruler
1458	
1459	/// The floating ruler band: adaptive ticks, the in/out shading, the marker
1460	/// flags and the playhead's coral head (spec §4.4).
1461	///
1462	/// Its frame's x is always 0 and its width the whole content, so its local x
1463	/// IS content x and every tick can be placed straight from the layout. Only
1464	/// its y floats. It refuses hits so `TimelineContentView` owns the mouse; the
1465	/// one exception is a real subview, which is how the inline rename field
1466	/// still works.
1467	final class TimelineRulerView: NSView {
1468	    weak var timeline: TimelineView?
1469	
1470	    override var isFlipped: Bool { true }
1471	
1472	    override init(frame frameRect: NSRect) {
1473	        super.init(frame: frameRect)
1474	    }
1475	
1476	    @available(*, unavailable)
1477	    required init?(coder: NSCoder) {
1478	        fatalError("TimelineRulerView does not support NSCoder")
1479	    }
1480	
1481	    override func hitTest(_ point: NSPoint) -> NSView? {
1482	        let hit = super.hitTest(point)
1483	        return hit === self ? nil : hit
1484	    }
1485	
1486	    override func draw(_ dirtyRect: NSRect) {
1487	        guard let owner = timeline else { return }
1488	        let layout = owner.layout
1489	        DS.chromeBackground.setFill()
1490	        bounds.fill()
1491	
1492	        if let range = owner.inOutRange, range.end > range.start {
1493	            DS.timelineRangeShade.setFill()
1494	            NSRect(
1495	                x: layout.x(for: range.start), y: 0,
1496	                width: layout.width(of: range.end - range.start), height: bounds.height
1497	            ).fill()
1498	        }
1499	        drawSelectedActionSpan(owner: owner, layout: layout)
1500	        drawCandidateSpans(owner: owner, layout: layout)
1501	
1502	        let steps = layout.rulerSteps()
1503	        let range = layout.visibleRange(dirtyRect)
1504	        drawTicks(steps: steps, range: range, layout: layout)
1505	        drawMarkers(owner: owner, layout: layout)
1506	
1507	        // The corner covers the ticks that would otherwise slide under the
1508	        // header column, and it is drawn last for exactly that reason.
1509	        let corner = NSRect(
1510	            x: owner.pinnedX, y: 0, width: TimelineLayout.headerWidth, height: bounds.height)
1511	        DS.chromeBackground.setFill()
1512	        corner.fill()
1513	        DS.border.setFill()
1514	        NSRect(x: corner.maxX - 1, y: 0, width: 1, height: bounds.height).fill()
1515	        NSRect(x: 0, y: bounds.height - 1, width: bounds.width, height: 1).fill()
1516	        drawBreadcrumb(owner: owner, in: corner)
1517	
1518	        drawPlayheadHead(owner: owner, layout: layout)
1519	    }
1520	
1521	    /// Minors and majors walk their OWN grids rather than the majors being
1522	    /// "every nth minor".
1523	    ///
1524	    /// **Pitfall:** at 29.97 a frame is 20 020 ticks and a second is 600 000,
1525	    /// which is not a multiple of it — testing `time.isMultiple(of: major)`
1526	    /// inside the minor loop would land only on zero and the ruler would lose
1527	    /// every label on exactly the rates that need them most.
1528	    private func drawTicks(
1529	        steps: (minor: Ticks, major: Ticks), range: (start: Ticks, end: Ticks),
1530	        layout: TimelineLayout
1531	    ) {
1532	        guard steps.minor > 0, steps.major > 0 else { return }
1533	        DS.borderStrong.setFill()
1534	        var minor = max((range.start / steps.minor) * steps.minor, 0)
1535	        while minor <= range.end {
1536	            NSRect(x: layout.x(for: minor).rounded(), y: bounds.height - 6, width: 1, height: 5)
1537	                .fill()
1538	            minor += steps.minor
1539	        }
1540	        var major = max((range.start / steps.major) * steps.major, 0)
1541	        while major <= range.end {
1542	            defer { major += steps.major }
1543	            NSRect(x: layout.x(for: major).rounded(), y: bounds.height - 10, width: 1, height: 9)
1544	                .fill()
1545	            TimelineDraw.label(
1546	                layout.rulerLabel(major),
1547	                in: CGRect(
1548	                    x: layout.x(for: major) + 3, y: 2, width: layout.width(of: steps.major) - 4,
1549	                    height: 12),
1550	                font: DS.mono(9), color: DS.textMuted)
1551	        }
1552	    }
1553	
1554	    private func drawMarkers(owner: TimelineView, layout: TimelineLayout) {
1555	        for marker in owner.snapshot.markers {
1556	            let x = layout.x(for: marker.time).rounded()
1557	            let flag = NSBezierPath()
1558	            flag.move(to: NSPoint(x: x, y: 3))
1559	            flag.line(to: NSPoint(x: x + 9, y: 6))
1560	            flag.line(to: NSPoint(x: x, y: 9))
1561	            flag.close()
1562	            let color = markerColor(marker.color)
1563	            if marker.chapter {
1564	                color.setFill()
1565	                flag.fill()
1566	            } else {
1567	                color.setStroke()
1568	                flag.lineWidth = 1
1569	                flag.stroke()
1570	            }
1571	            color.setFill()
1572	            NSRect(x: x, y: 3, width: 1, height: bounds.height - 5).fill()
1573	        }
1574	    }
1575	
1576	    /// The model stores a colour NAME (spec §5.2), not components; the
1577	    /// vocabulary is `ClipLabel`'s, shared with the clip label dot.
1578	    private func markerColor(_ name: String) -> NSColor {
1579	        ClipLabel.color(named: name)
1580	    }
1581	
1582	    private func drawPlayheadHead(owner: TimelineView, layout: TimelineLayout) {
1583	        let x = layout.x(for: owner.playhead).rounded()
1584	        guard x >= owner.pinnedX + TimelineLayout.headerWidth else { return }
1585	        DS.playhead.setFill()
1586	        let head = NSBezierPath()
1587	        head.move(to: NSPoint(x: x - 5, y: bounds.height - 10))
1588	        head.line(to: NSPoint(x: x + 5, y: bounds.height - 10))
1589	        head.line(to: NSPoint(x: x, y: bounds.height - 1))
1590	        head.close()
1591	        head.fill()
1592	        NSRect(x: x - 0.5, y: 0, width: 1, height: bounds.height).fill()
1593	    }
1594	}
