1628	    static func buttonRect(_ index: Int, height: CGFloat) -> CGRect {
1629	        CGRect(
1630	            x: buttonInset + CGFloat(index) * (buttonSize + 3),
1631	            // Never above 16 pt: on a Small track the name label owns the top
