1640	    static func button(at local: CGPoint, height: CGFloat) -> TimelineHeaderButton? {
1641	        let buttons: [TimelineHeaderButton] = [.hidden, .muted, .locked, .solo, .mix]
1642	        for (index, button) in buttons.enumerated()
1643	        where buttonRect(index, height: height).insetBy(dx: -1, dy: -1).contains(local) {
