1662	            DS.chromeBackground.setFill()
1663	            rect.fill()
1664	            DS.border.setFill()
1665	            NSRect(x: 0, y: rect.maxY, width: bounds.width, height: 1).fill()
1666	
1667	            TimelineDraw.label(
1668	                track.name.isEmpty ? "Track \(index + 1)" : track.name,
1669	                in: CGRect(
1670	                    x: 8, y: rect.minY + 2,
1671	                    width: bounds.width - 14 - matteTagWidth(track, rowHeight: height), height: 13),
1672	                font: DS.sans(11, weight: .semibold), color: DS.textStrong)
