1674	
1675	            let toggles: [(TimelineHeaderButton, String, String, Bool)] = [
1676	                (.hidden, track.hidden ? "eye.slash" : "eye", "H", track.hidden),
1677	                (.muted, track.muted ? "speaker.slash" : "speaker.wave.2", "M", track.muted),
