1200	    // MARK: Regions
1201	
1202	    /// Spec §4.4's split: a filmstrip over a waveform on a video clip with
1203	    /// sound, the whole bar for one that has only the one.
1204	    static func regions(
1205	        in rect: CGRect, hasVideo: Bool, hasAudio: Bool
1206	    ) -> (video: CGRect, audio: CGRect) {
1207	        switch (hasVideo, hasAudio) {
1208	        case (true, true):
1209	            let top = (rect.height * 0.56).rounded()
1210	            return (
1211	                CGRect(x: rect.minX, y: rect.minY, width: rect.width, height: top),
1212	                CGRect(
1213	                    x: rect.minX, y: rect.minY + top, width: rect.width,
1214	                    height: rect.height - top)
1215	            )
1216	        case (true, false): return (rect, .zero)
1217	        case (false, true): return (.zero, rect)
1218	        case (false, false): return (.zero, .zero)
1219	        }
1220	    }
1221	
1222	    /// The square handle for one fade, at the audio region's corner when the
1223	    /// fade is zero and at the fade's end once it has been dragged in.
1224	    static func fadeRect(
1225	        _ clip: ClipSnapshot, edge: TimelineEdge, audio: CGRect, layout: TimelineLayout
1226	    ) -> CGRect {
1227	        let props = clip.audioProps
1228	        let side = TimelineLayout.fadeHandle
1229	        let time = edge == .start ? clip.start + props.fadeIn : clip.end - props.fadeOut
1230	        let x = min(max(layout.x(for: time), audio.minX), max(audio.maxX - side, audio.minX))
1231	        return CGRect(x: x - (edge == .start ? 0 : side), y: audio.minY, width: side, height: side)
1232	    }
1233	
1234	    // MARK: Hit testing
1235	
1236	    func hit(at point: CGPoint) -> TimelineHit {
1237	        guard let owner = timeline else { return .none }
1238	        let layout = owner.layout
1239	        let snapshot = owner.snapshot
1240	
1241	        if point.y >= owner.pinnedY, point.y < owner.pinnedY + TimelineLayout.rulerHeight {
1242	            if point.x < owner.pinnedX + TimelineLayout.headerWidth { return owner.cornerHit }
1243	            for marker in snapshot.markers
1244	            where abs(layout.x(for: marker.time) - point.x) <= 6 {
1245	                return .marker(marker.id)
1246	            }
1247	            return .ruler(max(layout.time(atX: point.x), 0))
1248	        }
1249	
1250	        if point.x < owner.pinnedX + TimelineLayout.headerWidth {
1251	            guard let row = layout.row(atY: point.y) else { return .none }
1252	            let local = CGPoint(x: point.x - owner.pinnedX, y: point.y - layout.rowTop(row))
1253	            let lane = layout.trackHeight(row: row)
1254	            if let button = TimelineHeaderView.button(at: local, height: lane) {
1255	                return .headerButton(row: row, button: button)
1256	            }
1257	            return .header(row: row)
1258	        }
1259	
1260	        guard let row = layout.row(atY: point.y) else { return .outside }
1261	        guard let track = owner.track(atRow: row) else { return .none }
1262	        for clip in snapshot.clips(onTrack: track.id) {
1263	            let rect = layout.clipRect(clip, row: row)
1264	            guard point.x >= rect.minX - 1, point.x <= rect.maxX + 1 else { continue }
1265	            guard !track.locked else { return .clip(clip.id) }
1266	            if owner.hasAudio(clip) {
1267	                // The same rectangle the waveform is drawn in
1268	                // (`TimelineClipDrawing.contentRect`), never the lane rect —
1269	                // the fade handles sit under the clip's name strip.
1270	                let audio = Self.regions(
1271	                    in: Self.contentRect(rect), hasVideo: owner.hasVideo(clip), hasAudio: true
1272	                ).audio
1273	                for edge in [TimelineEdge.start, TimelineEdge.end]
1274	                where Self.fadeRect(clip, edge: edge, audio: audio, layout: layout)
1275	                    .insetBy(dx: -2, dy: -2).contains(point) {
1276	                    return .fade(clip.id, edge)
1277	                }
1278	            }
1279	            if let hit = actionHit(clip, rect: rect, at: point) { return hit }
1280	            // A bar too narrow to hold two grab zones is all body: trimming a
1281	            // 3 pt clip by eye is not an interaction, it is a trap.
1282	            if rect.width > TimelineLayout.edgeGrab * 3 {
1283	                if point.x - rect.minX <= TimelineLayout.edgeGrab {
1284	                    return .clipEdge(clip.id, .start)
1285	                }
1286	                if rect.maxX - point.x <= TimelineLayout.edgeGrab {
1287	                    return .clipEdge(clip.id, .end)
1288	                }
1289	            }
1290	            if let hit = volumeLineHit(clip, rect: rect, at: point) { return hit }
1291	            return .clip(clip.id)
1292	        }
1293	        return .lane(row: row, time: max(layout.time(atX: point.x), 0))
1294	    }
