1395	
1396	        for (index, track) in snapshot.tracks.enumerated() {
1397	            let row = layout.row(forTrackIndex: index)
1398	            let lane = layout.rowRect(row, width: layout.contentWidth)
1399	            guard lane.intersects(dirtyRect) else { continue }
1400	            drawClips(
1401	                snapshot.clips(onTrack: track.id), row: row, track: track, owner: owner,
1402	                dirtyRect: dirtyRect)
