315	/// What a drag on the line edits (AU-82): the clip's base volume, or an
316	/// action's end; each with the value it starts from.
317	enum VolumeLineTarget: Equatable {
318	    case base(volume: Double)
319	    case end(action: UInt32, volume: Double)
320	
321	    var volume: Double {
322	        switch self {
323	        case .base(let volume), .end(_, let volume): return volume
324	        }
325	    }
326	}
