588	/// Retiming an action by drag (spec §11 CI-11, §6 `set_action`), the ONE
589	/// session the timeline's lane and the Clip tab's lane both drag with.
590	///
591	/// Everything here is CLIP time. Every tick sends start AND duration, frame
592	/// snapped, as one `set_action`; `ProjectDocument.updateLiveEdit` re-applies
593	/// it to the handle the gesture started from, so the ops never compound.
594	///
595	/// The clamp is a PREVIEW clamp, `TrimSession`'s kind: it mirrors the two
596	/// walls the core's refusals name — another action (`edit_action.rs`
597	/// `overlapping_action`, `start < o.end && o.start < end`, which makes a
598	/// zero-length action at the band's start or end a wall) and the clip's own
599	/// length — so the band stops where the core would refuse. It does not
600	/// replace the core's check; a tick the core still refuses is swallowed.
601	///
602	/// `originalDuration > 0` is an invariant both callers hold: a zero-length
603	/// action is never dragged, because `duration: 0` is invalid input to the
604	/// core (the `err_out` channel), not a refusal.
605	struct ActionDragSession {
606	    let clip: UInt32
607	    let action: UInt32
608	    let mode: ActionDragMode
609	    let originalStart: Ticks
610	    let originalDuration: Ticks
611	    /// Pointer clip time − `originalStart` at mouse-down, so the band keeps
612	    /// its place under the pointer instead of jumping to it.
613	    let grabOffset: Ticks
614	    /// One frame of the document's grid: the minimum length, the core's own.
615	    let frame: Ticks
616	    /// The latest end at or before `originalStart` among the clip's OTHER
617	    /// actions, or 0.
618	    let lowerWall: Ticks
619	    /// The earliest start at or after the original end among the clip's
620	    /// OTHER actions, or the clip's length floored to the frame grid.
621	    let upperWall: Ticks
622	    let fps: Fps
623	
624	    var start: Ticks
625	    var duration: Ticks
626	    /// False until the pointer moves — a press that only selects registers
627	    /// no undo step.
628	    var didMove = false
629	
630	    init(
631	        clip: ClipSnapshot, action: ActionSnapshot, mode: ActionDragMode, grabAt clipTime: Ticks,
632	        fps: Fps
633	    ) {
634	        self.clip = clip.id
635	        self.action = action.id
636	        self.mode = mode
637	        originalStart = action.start
638	        originalDuration = action.duration
639	        grabOffset = clipTime - action.start
640	        frame = max(fps.frameDuration, 1)
641	        self.fps = fps
642	        let end = action.endTime
643	        var lower: Ticks = 0
