665	    /// `clipTime` is the pointer's clip time. The grabbed edge (both edges,
666	    /// for a move) travels by the pointer's travel, snapped to the frame
667	    /// grid, then clamped to the walls and the one-frame minimum.
668	    mutating func update(clipTime: Ticks) {
669	        let low = lowerWall, high = upperWall
670	        let travel = clipTime - (originalStart + grabOffset)
671	        let originalEnd = originalStart + originalDuration
672	        switch mode {
673	        case .move:
674	            let proposed = ReelTime.snapToFrame(originalStart + travel, fps: fps)
675	            start = max(min(proposed, high - originalDuration), low)
676	            duration = originalDuration
677	        case .resize(.start):
678	            let proposed = ReelTime.snapToFrame(originalStart + travel, fps: fps)
679	            start = max(min(proposed, originalEnd - frame), low)
680	            duration = originalEnd - start
681	        case .resize(.end):
682	            let proposed = ReelTime.snapToFrame(originalEnd + travel, fps: fps)
683	            let end = min(max(proposed, originalStart + frame), high)
684	            start = originalStart
685	            duration = end - originalStart
686	        }
687	        didMove = true
688	    }
