690	    /// The HUD's text. A move or a start resize: "new start → new end  +s:ff"
691	    /// (the start's offset, in seconds and frames); an end resize:
692	    /// "len +Nf". `base` turns clip time into the time the caller shows.
693	    func hud(base: Ticks, frames: Bool) -> String {
694	        if mode == .resize(.end) {
695	            let delta = (duration - originalDuration) / frame
696	            return "len \(delta < 0 ? "−" : "+")\(abs(delta))f"
697	        }
698	        let from = ReelTime.format(base + start, fps: fps, frames: frames)
699	        let to = ReelTime.format(base + endTime, fps: fps, frames: frames)
700	        let offset = start - originalStart
701	        let magnitude = abs(offset)
702	        let seconds = magnitude / ReelTime.perSecond
703	        let rest = (magnitude % ReelTime.perSecond) / frame
704	        let sign = offset < 0 ? "−" : "+"
705	        return "\(from) → \(to)  \(sign)\(seconds):\(rest < 10 ? "0" : "")\(rest)"
706	    }
