201	/// The volume line's model (road map "audio" AP8a, spec §11 AU-80…AU-84): the
202	/// dB scale it is drawn on, the plan's envelope per clip, what a press on it
203	/// edits, the ops a point is made of, and the drag's session. The drawing and
204	/// the gesture's wiring are `TimelineView+VolumeLine.swift`.
205	///
206	/// **The line is a view of actions** (AU-80): a point is an action's END
207	/// (`end.audio.volume`), a drag writes `set_audio {volume}` or that end, and
208	/// nothing is persisted that actions do not already persist.
209	
210	/// The line's dB scale (AU-81): +30.103 dB (`AudioNormalize.maxGain`, ×32) at
211	/// the top of `rect`, −60 dB at its bottom. A gain at or under 0.001 draws at
212	/// the bottom, one above 32 (a track's volume can carry the plan there,
213	/// AU-103) at the top. `rect` is the line's rect inset 1 pt top and bottom,
214	/// in the timeline content view's flipped space (its top is `minY`).
215	struct VolumeScale: Equatable {
216	    static let topDB: Double = 20 * log10(AudioNormalize.maxGain)
217	    static let floorDB: Double = -60
218	    let rect: CGRect
219	
220	    /// The y of `gain` (linear).
221	    func y(gain: Double) -> CGFloat {
222	        let db = gain > 0.001 ? 20 * log10(gain) : Self.floorDB
223	        let clamped = min(max(db, Self.floorDB), Self.topDB)
224	        let fraction = (Self.topDB - clamped) / (Self.topDB - Self.floorDB)
225	        return rect.minY + CGFloat(fraction) * rect.height
226	    }
227	
228	    /// The dB a pointer travel of `deltaY` (press y minus pointer y, so
229	    /// positive is UP) spans on this scale.
230	    func decibels(deltaY: CGFloat) -> Double {
231	        guard rect.height > 0 else { return 0 }
232	        return Double(deltaY / rect.height) * (Self.topDB - Self.floorDB)
233	    }
234	}
