236	/// One handle's plan, read for the line (AU-81): clip id → the ramps of the
237	/// plan audio track holding that clip's audio segment, cut to the segment.
238	/// Decoded lazily, at most once, as `DuckCurves` is (`DuckSpeech.swift`), so
239	/// a refresh that draws no line never pays for the plan.
240	final class VolumeLines {
241	    /// The handle the lines were read from — the timeline's own
242	    /// (`ProjectDocument.editedProject`), which a point's evaluated volume is
243	    /// read from too.
244	    let project: ReelProject
245	    private var byClip: [UInt32: [PlanRamp]]?
246	
247	    init(_ project: ReelProject) {
248	        self.project = project
249	    }
250	
251	    /// The clip's envelope in the handle's time, or nil when the plan has no
252	    /// audio segment for it.
253	    func ramps(for clip: UInt32) -> [PlanRamp]? {
254	        if byClip == nil { byClip = Self.read(project.plan) }
255	        return byClip?[clip]
256	    }
257	
258	    private static func read(_ plan: CompositionPlan?) -> [UInt32: [PlanRamp]] {
259	        var found: [UInt32: [PlanRamp]] = [:]
260	        for track in plan?.audioTracks ?? [] {
261	            let ramps = track.ramps ?? []
262	            var spans: [UInt32: (start: Ticks, end: Ticks)] = [:]
263	            for segment in track.segments where segment.duration > 0 {
264	                let end = segment.start + segment.duration
265	                if let span = spans[segment.clip] {
266	                    spans[segment.clip] = (min(span.start, segment.start), max(span.end, end))
267	                } else {
268	                    spans[segment.clip] = (segment.start, end)
269	                }
270	            }
271	            for (clip, span) in spans where found[clip] == nil {
272	                found[clip] = cut(ramps, from: span.start, to: span.end)
273	            }
274	        }
275	        return found
276	    }
277	
278	    /// `ramps` cut to `[from, to)`, each leg interpolated where it is cut.
279	    static func cut(_ ramps: [PlanRamp], from: Ticks, to: Ticks) -> [PlanRamp] {
280	        ramps.compactMap { ramp in
281	            let end = ramp.start + ramp.duration
282	            let start = max(ramp.start, from)
283	            let stop = min(end, to)
284	            guard stop > start else { return nil }
285	            func value(_ t: Ticks) -> Double {
286	                guard ramp.duration > 0 else { return ramp.to }
287	                let f = Double(t - ramp.start) / Double(ramp.duration)
288	                return ramp.from + (ramp.to - ramp.from) * f
289	            }
290	            return PlanRamp(start: start, duration: stop - start, from: value(start), to: value(stop))
291	        }
292	    }
293	
294	    /// The gain the ramps give at `t`, or nil where none covers it. A ramp's
295	    /// end belongs to the next one; the last one's end is its own.
296	    static func gain(at t: Ticks, in ramps: [PlanRamp]) -> Double? {
297	        for ramp in ramps where ramp.start <= t && t < ramp.start + ramp.duration {
298	            let f = Double(t - ramp.start) / Double(max(ramp.duration, 1))
299	            return ramp.from + (ramp.to - ramp.from) * f
300	        }
301	        if let last = ramps.last, t == last.start + last.duration { return last.to }
302	        return nil
303	    }
304	}
