328	enum VolumeLine {
329	    /// AU-82: inside an action naming `end.audio.volume` → that action; else
330	    /// the latest action ENDED at or before `clipTime` naming it; else the base.
331	    static func target(of clip: ClipSnapshot, at clipTime: Ticks) -> VolumeLineTarget {
332	        let naming = clip.actions.filter { $0.end.audio?.volume != nil }
333	        if let inside = naming.first(where: { $0.start <= clipTime && clipTime < $0.endTime }),
334	           let volume = inside.end.audio?.volume {
335	            return .end(action: inside.id, volume: volume)
336	        }
337	        if let held = naming.filter({ $0.endTime <= clipTime }).max(by: { $0.endTime < $1.endTime }),
338	           let volume = held.end.audio?.volume {
339	            return .end(action: held.id, volume: volume)
340	        }
341	        return .base(volume: clip.audioProps.volume)
342	    }
343	
344	    /// AU-83: the ops BEFORE the dragged end, the action whose end is
345	    /// dragged and the value it starts at; nil where a point cannot go (the
346	    /// caller beeps). `clipTime` is snapped to the frame here.
347	    static func point(
348	        on clip: ClipSnapshot, at clipTime: Ticks, project: ReelProject, nextId: UInt32, fps: Fps
349	    ) -> (prefix: [ReelOp], action: UInt32, volume: Double)? {
350	        let frame = max(fps.frameDuration, 1)
351	        let t = ReelTime.snapToFrame(clipTime, fps: fps)
352	        guard t >= 0, t < clip.duration,
353	              let volume = (project.clipState(clip.id, at: clip.start + t)?["audio"]
354	                  as? [String: Any])?["volume"] as? Double
355	        else { return nil }
356	        if let inside = clip.actions.first(where: { $0.start <= t && t < $0.endTime }) {
357	            // An action a trim left running past the clip's end: `add_action`
358	            // would refuse its second half (`action_past_end`), silently.
359	            guard let end = inside.end.audio?.volume, namesOnlyVolume(inside.end),
360	                  t - inside.start >= frame, inside.endTime <= clip.duration
361	            else { return nil }
362	            var prefix: [ReelOp] = [
363	                .setAction(clip: clip.id, action: inside.id, duration: t - inside.start),
364	                .addAction(clip: clip.id, at: t, duration: inside.endTime - t),
365	                .setActionEnd(
366	                    clip: clip.id, action: nextId,
367	                    patch: ActionPatch(audio: AudioPatch(volume: end))),
368	            ]
369	            if inside.curve != .linear {
370	                prefix.append(.setAction(clip: clip.id, action: nextId, curve: inside.curve))
371	            }
372	            return (prefix, inside.id, volume)
373	        }
374	        let prevEnd = clip.actions.map(\.endTime).filter { $0 <= t }.max() ?? 0
375	        guard t - prevEnd >= frame else { return nil }
376	        return ([.addAction(clip: clip.id, at: prevEnd, duration: t - prevEnd)], nextId, volume)
377	    }
378	
379	    /// An end patch whose only key is `audio.volume`.
380	    static func namesOnlyVolume(_ end: ActionPatch) -> Bool {
381	        guard let volume = end.audio?.volume else { return false }
382	        return end.video == nil && end.text == nil && end.graphic == nil && end.speed == nil
383	            && end.audio == AudioPatch(volume: volume)
384	    }
385	
386	    /// AU-82: 0 at the bottom; else `start` (at least 0.001, so a silent
387	    /// value can be raised) moved by `decibels`, held to `check_audio`'s
388	    /// 0…32. `atBottom` is the caller's "pointer below the press and at the
389	    /// scale's `maxY − 1` or lower".
390	    static func volume(from start: Double, decibels: Double, atBottom: Bool) -> Double {
391	        if atBottom { return 0 }
392	        return min(max(max(start, 0.001) * pow(10, decibels / 20), 0), AudioNormalize.maxGain)
393	    }
394	
395	    /// The drag's readout: "+2.5 dB", one decimal, "−∞ dB" at 0.
396	    static func readout(_ volume: Double) -> String {
397	        guard volume > 0 else { return "\u{2212}\u{221E} dB" }
398	        let db = 20 * log10(volume)
399	        let text = String(format: "%.1f", abs(db))
400	        if text == "0.0" { return "0.0 dB" }
401	        return (db < 0 ? "\u{2212}" : "+") + text + " dB"
402	    }
403	}
