405	/// One drag on the line (AU-82, AU-83): the ops each tick sends are the
406	/// point's `prefix` (empty for a plain drag) and the write of `volume` to the
407	/// target.
408	struct VolumeLineSession {
409	    let clip: UInt32
410	    let target: VolumeLineTarget
411	    let prefix: [ReelOp]
412	    let pressY: CGFloat
413	    let scale: VolumeScale
414	    var volume: Double
415	    /// The pointer, for the readout.
416	    var point: CGPoint
417	
418	    var ops: [ReelOp] {
419	        switch target {
420	        case .base:
421	            return prefix + [.setAudio(clips: [clip], patch: AudioPatch(volume: volume))]
422	        case .end(let action, _):
423	            return prefix + [.setActionEnd(
424	                clip: clip, action: action, patch: ActionPatch(audio: AudioPatch(volume: volume)))]
425	        }
426	    }
427	
428	    var undoName: String { prefix.isEmpty ? "Set Volume" : "Add Volume Point" }
429	
430	    mutating func update(y: CGFloat) {
431	        volume = VolumeLine.volume(
432	            from: target.volume, decibels: scale.decibels(deltaY: pressY - y),
433	            atBottom: y > pressY && y >= scale.rect.maxY - 1)
434	    }
435	}
