588	/// Retiming an action by drag (spec §11 CI-11, §6 `set_action`), the ONE
589	/// session the timeline's lane and the Clip tab's lane both drag with.
590	///
591	/// Everything here is CLIP time. Every tick sends start AND duration, frame
592	/// snapped, as one `set_action`; `ProjectDocument.updateLiveEdit` re-applies
593	/// it to the handle the gesture started from, so the ops never compound.
594	///
595	/// The clamp is a PREVIEW clamp, `TrimSession`'s kind: it mirrors the two
596	/// walls the core's refusals name — another action (`edit_action.rs`
597	/// `overlapping_action`, `start < o.end && o.start < end`, which makes a
598	/// zero-length action at the band's start or end a wall) and the clip's own
599	/// length — so the band stops where the core would refuse. It does not
600	/// replace the core's check; a tick the core still refuses is swallowed.
601	///
602	/// `originalDuration > 0` is an invariant both callers hold: a zero-length
603	/// action is never dragged, because `duration: 0` is invalid input to the
604	/// core (the `err_out` channel), not a refusal.
605	struct ActionDragSession {
606	    let clip: UInt32
607	    let action: UInt32
608	    let mode: ActionDragMode
609	    let originalStart: Ticks
610	    let originalDuration: Ticks
611	    /// Pointer clip time − `originalStart` at mouse-down, so the band keeps
612	    /// its place under the pointer instead of jumping to it.
613	    let grabOffset: Ticks
614	    /// One frame of the document's grid: the minimum length, the core's own.
615	    let frame: Ticks
616	    /// The latest end at or before `originalStart` among the clip's OTHER
617	    /// actions, or 0.
618	    let lowerWall: Ticks
619	    /// The earliest start at or after the original end among the clip's
620	    /// OTHER actions, or the clip's length floored to the frame grid.
621	    let upperWall: Ticks
622	    let fps: Fps
623	
624	    var start: Ticks
625	    var duration: Ticks
626	    /// False until the pointer moves — a press that only selects registers
627	    /// no undo step.
628	    var didMove = false
629	
630	    init(
631	        clip: ClipSnapshot, action: ActionSnapshot, mode: ActionDragMode, grabAt clipTime: Ticks,
632	        fps: Fps
633	    ) {
634	        self.clip = clip.id
635	        self.action = action.id
636	        self.mode = mode
637	        originalStart = action.start
638	        originalDuration = action.duration
639	        grabOffset = clipTime - action.start
640	        frame = max(fps.frameDuration, 1)
641	        self.fps = fps
642	        let end = action.endTime
643	        var lower: Ticks = 0
644	        // Floored: an off-grid length would let a clamped edge snap past it.
645	        // Never below the action's own end, or a move would clamp it left.
646	        var upper = max(clip.duration - clip.duration % frame, end)
647	        for other in ActionBands.ordered(clip) where other.id != action.id {
648	            if other.endTime <= action.start { lower = max(lower, other.endTime) }
649	            if other.start >= end { upper = min(upper, other.start) }
650	        }
651	        lowerWall = max(0, lower)
652	        upperWall = upper
653	        start = action.start
654	        duration = action.duration
655	    }
656	
657	    var endTime: Ticks { start + duration }
658	
659	    var changed: Bool { start != originalStart || duration != originalDuration }
660	
661	    var op: ReelOp { .setAction(clip: clip, action: action, start: start, duration: duration) }
662	
663	    var undoName: String { mode == .move ? "Move Action" : "Resize Action" }
664	
665	    /// `clipTime` is the pointer's clip time. The grabbed edge (both edges,
666	    /// for a move) travels by the pointer's travel, snapped to the frame
667	    /// grid, then clamped to the walls and the one-frame minimum.
668	    mutating func update(clipTime: Ticks) {
669	        let low = lowerWall, high = upperWall
670	        let travel = clipTime - (originalStart + grabOffset)
671	        let originalEnd = originalStart + originalDuration
672	        switch mode {
673	        case .move:
674	            let proposed = ReelTime.snapToFrame(originalStart + travel, fps: fps)
675	            start = max(min(proposed, high - originalDuration), low)
676	            duration = originalDuration
677	        case .resize(.start):
678	            let proposed = ReelTime.snapToFrame(originalStart + travel, fps: fps)
679	            start = max(min(proposed, originalEnd - frame), low)
680	            duration = originalEnd - start
681	        case .resize(.end):
682	            let proposed = ReelTime.snapToFrame(originalEnd + travel, fps: fps)
683	            let end = min(max(proposed, originalStart + frame), high)
684	            start = originalStart
685	            duration = end - originalStart
686	        }
687	        didMove = true
688	    }
689	
690	    /// The HUD's text. A move or a start resize: "new start → new end  +s:ff"
691	    /// (the start's offset, in seconds and frames); an end resize:
692	    /// "len +Nf". `base` turns clip time into the time the caller shows.
693	    func hud(base: Ticks, frames: Bool) -> String {
694	        if mode == .resize(.end) {
695	            let delta = (duration - originalDuration) / frame
696	            return "len \(delta < 0 ? "−" : "+")\(abs(delta))f"
697	        }
698	        let from = ReelTime.format(base + start, fps: fps, frames: frames)
699	        let to = ReelTime.format(base + endTime, fps: fps, frames: frames)
700	        let offset = start - originalStart
701	        let magnitude = abs(offset)
702	        let seconds = magnitude / ReelTime.perSecond
703	        let rest = (magnitude % ReelTime.perSecond) / frame
704	        let sign = offset < 0 ? "−" : "+"
705	        return "\(from) → \(to)  \(sign)\(seconds):\(rest < 10 ? "0" : "")\(rest)"
706	    }
707	}
